<template>
  <section class="home-showcase"><header class="rd-page-header"><div><p class="rd-eyebrow">MADE BY RD STUDIO</p><h2>从想法，到作品</h2></div><a class="rd-button" href="/games-tools/">全部作品<ArrowUpRight :size="17" /></a></header><p v-if="loading" class="knowledge-empty" role="status">正在加载作品…</p><p v-else-if="error" role="alert">{{ error }} <button class="rd-button" @click="load">重试</button></p><div v-else-if="items.length" class="home-work-grid"><a v-for="item in items" :key="item.id" :href="'/games-tools/?id='+encodeURIComponent(item.id)"><img v-if="item.cover_url" :src="item.cover_url" :alt="item.title" loading="lazy"><div v-else class="home-work-cover"><Gamepad2 v-if="item.kind==='game'" :size="40" /><Wrench v-else :size="40" /></div><div class="home-work-text"><small>{{ item.kind==='game' ? '游戏' : '工具' }} · {{ item.platform || '创作分享' }}</small><h3>{{ item.title }}</h3><p>{{ item.summary }}</p><footer><span>{{ item.username }}</span><span><Download :size="14" />{{ item.downloads }}</span></footer></div></a></div><div v-else class="home-work-empty"><Gamepad2 :size="30" /><p>还没有公开作品</p><a class="rd-button" href="/games-tools/">发布作品<ArrowUpRight :size="17" /></a></div></section>
  <section class="home-community"><HomeArticles /><aside class="home-community-aside"><section><p class="rd-eyebrow">MAKE IT HAPPEN</p><h2>今天，向前一步</h2><a href="/tasks/"><ListChecks :size="20" /><span>任务与经验</span><ArrowUpRight :size="17" /></a><button @click="checkin"><CalendarCheck :size="20" /><span>每日签到</span><ArrowUpRight :size="17" /></button><a href="/user/profile?tab=recent"><History :size="20" /><span>继续上次阅读</span><ArrowUpRight :size="17" /></a></section><WeeklyActivity compact /><section><p class="rd-eyebrow">FIND YOUR PEOPLE</p><h2>一起创造</h2><p>程序 · 美术 · 技术美术 · 策划 · 运营</p><a href="/about/"><UsersRound :size="20" /><span>加入 RD STUDIO</span><ArrowUpRight :size="17" /></a><a href="/messages/"><Bell :size="20" /><span>我的消息</span><ArrowUpRight :size="17" /></a></section></aside></section>
</template>
<script setup>
import { onMounted,onUnmounted,ref } from 'vue'
import { ArrowUpRight,Bell,CalendarCheck,Download,Gamepad2,History,ListChecks,UsersRound,Wrench } from 'lucide-vue-next'
import HomeArticles from './HomeArticles.vue'
import WeeklyActivity from './WeeklyActivity.vue'
import { communityRequest } from '../lib/community-api.mjs'
const items=ref([]),loading=ref(true),error=ref('');let disposed=false,revision=0
async function load(){const run=++revision;loading.value=true;error.value='';try{const result=await communityRequest('/catalog');if(!disposed&&run===revision)items.value=result.items.slice(0,3)}catch(cause){if(!disposed&&run===revision)error.value=cause.message}finally{if(!disposed&&run===revision)loading.value=false}}
async function checkin(){try{const auth=await window.__api?.auth.getUser();if(auth?.data?.user)window.dispatchEvent(new CustomEvent('rd:checkin'));else window.location.assign('/login/')}catch{window.location.assign('/login/')}}
onMounted(load);onUnmounted(()=>{disposed=true;++revision})
</script>
